package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.jsoup.Connection;
import org.jsoup.Jsoup;
import org.jsoup.helper.HttpConnection;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Connection.KeyVal;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.FormElement;
import org.jsoup.parser.Tag;
import org.jsoup.select.Elements;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class FormElement_formData_TriageGen2Test {

    @Test
    public void testFormData_NoElements() {
        FormElement form = new FormElement(null, null, null);
        List<KeyVal> result = form.formData();
        assertTrue(result.isEmpty());
    }

    @Test
    public void testFormData_NoFormSubmittableElements() {
        FormElement form = mock(FormElement.class);
        when(form.elements()).thenReturn(new Elements());
        List<KeyVal> result = form.formData();
        assertTrue(result.isEmpty());
    }

    @Test
    public void testFormData_SelectedOption() {
        FormElement form = mock(FormElement.class);
        when(form.elements()).thenReturn(new Elements(
                mock(Element.class).withAttr("name", "test").withAttr("type", "select")
                        .withSelect("option[selected]", new Elements(mock(Element.class).withAttr("value", "value1")))));
        List<KeyVal> result = form.formData();
        assertEquals(1, result.size());
        KeyVal keyVal = result.get(0);
        assertEquals("test", keyVal.key());
        assertEquals("value1", keyVal.val());
    }

    @Test
    public void testFormData_SelectedOptionNoValue() {
        FormElement form = mock(FormElement.class);
        when(form.elements()).thenReturn(new Elements(
                mock(Element.class).withAttr("name", "test").withAttr("type", "select")
                        .withSelect("option[selected]", new Elements())));
        List<KeyVal> result = form.formData();
        assertTrue(result.isEmpty());
    }

    @Test
    public void testFormData_SelectedOptionNoSelected() {
        FormElement form = mock(FormElement.class);
        when(form.elements()).thenReturn(new Elements(
                mock(Element.class).withAttr("name", "test").withAttr("type", "select")
                        .withSelect("option[selected]", new Elements())));
        List<KeyVal> result = form.formData();
        assertEquals(1, result.size());
        KeyVal keyVal = result.get(0);
        assertEquals("test", keyVal.key());
        assertEquals(mock(Element.class).val(), keyVal.val());
    }

    @Test
    public void testFormData_CheckboxChecked() {
        FormElement form = mock(FormElement.class);
        when(form.elements()).thenReturn(new Elements(
                mock(Element.class).withAttr("name", "test").withAttr("type", "checkbox").withAttr("checked", "true")));
        List<KeyVal> result = form.formData();
        assertEquals(1, result.size());
        KeyVal keyVal = result.get(0);
        assertEquals("test", keyVal.key());
        assertEquals(mock(Element.class).val(), keyVal.val());
    }

    @Test
    public void testFormData_CheckboxUnchecked() {
        FormElement form = mock(FormElement.class);
        when(form.elements()).thenReturn(new Elements(
                mock(Element.class).withAttr("name", "test").withAttr("type", "checkbox")));
        List<KeyVal> result = form.formData();
        assertTrue(result.isEmpty());
    }

    @Test
    public void testFormData_RadioChecked() {
        FormElement form = mock(FormElement.class);
        when(form.elements()).thenReturn(new Elements(
                mock(Element.class).withAttr("name", "test").withAttr("type", "radio").withAttr("checked", "true")));
        List<KeyVal> result = form.formData();
        assertEquals(1, result.size());
        KeyVal keyVal = result.get(0);
        assertEquals("test", keyVal.key());
        assertEquals(mock(Element.class).val(), keyVal.val());
    }

    @Test
    public void testFormData_RadioUnchecked() {
        FormElement form = mock(FormElement.class);
        when(form.elements()).thenReturn(new Elements(
                mock(Element.class).withAttr("name", "test").withAttr("type", "radio")));
        List<KeyVal> result = form.formData();
        assertTrue(result.isEmpty());
    }

    @Test
    public void testFormData_Text() {
        FormElement form = mock(FormElement.class);
        when(form.elements()).thenReturn(new Elements(
                mock(Element.class).withAttr("name", "test").withAttr("value", "value")));
        List<KeyVal> result = form.formData();
        assertEquals(1, result.size());
        KeyVal keyVal = result.get(0);
        assertEquals("test", keyVal.key());
        assertEquals("value", keyVal.val());
    }

    @Test
    public void testFormData_NullName() {
        FormElement form = mock(FormElement.class);
        when(form.elements()).thenReturn(new Elements(
                mock(Element.class).withAttr("name", null).withAttr("value", "value")));
        List<KeyVal> result = form.formData();
        assertTrue(result.isEmpty());
    }

    @Test
    public void testFormData_EmptyName() {
        FormElement form = mock(FormElement.class);
        when(form.elements()).thenReturn(new Elements(
                mock(Element.class).withAttr("name", "").withAttr("value", "value")));
        List<KeyVal> result = form.formData();
        assertTrue(result.isEmpty());
    }

    @Test
    public void testFormData_NullValue() {
        FormElement form = mock(FormElement.class);
        when(form.elements()).thenReturn(new Elements(
                mock(Element.class).withAttr("name", "test").withAttr("value", null)));
        List<KeyVal> result = form.formData();
        assertTrue(result.isEmpty());
    }
}
